    11→import com.cowave.search.domain.proxy.manufacturer.Manufacturer
    12→import com.cowave.search.domain.proxy.manufacturer.ManufacturerService
    13→import kotlinx.coroutines.Dispatchers
    14→import kotlinx.coroutines.async
    15→import kotlinx.coroutines.runBlocking
    16→import org.springframework.stereotype.Service
    17→
    18→@Service
    19→class ProxyApplicationService(
    20→    private val brandService: BrandService,
    21→    private val manufacturerService: ManufacturerService,
    22→    private val categoryService: CategoryService,
    23→    private val mallService: MallService,
    24→) {
    25→    fun fetchDependencies(dependencyId: DependencyId): Dependency =
    26→        runBlocking(Dispatchers.IO) {
    27→            val categoriesDeferred =
    28→                async {
    29→                    if (dependencyId.categoryIds.isEmpty()) {
    30→                        emptyMap()
    31→                    } else {
    32→                        categoryService.getCategories(dependencyId.categoryIds).associateBy { it.id }
    33→                    }
    34→                }
    35→            val brandsDeferred =
    36→                async {
    37→                    if (dependencyId.brandIds.isEmpty()) {
    38→                        emptyMap()
    39→                    } else {
    40→                        brandService.getBrands(dependencyId.brandIds).associateBy { it.id }
    41→                    }
    42→                }
    43→            val manufacturersDeferred =
    44→                async {
    45→                    if (dependencyId.manufacturerIds.isEmpty()) {
    46→                        emptyMap()
    47→                    } else {
    48→                        manufacturerService.getManufacturers(dependencyId.manufacturerIds).associateBy { it.id }
    49→                    }
    50→                }
    51→            val mallsDeferred =
    52→                async {
    53→                    if (dependencyId.mallIds.isEmpty()) {
    54→                        emptyMap()
    55→                    } else {
    56→                        mallService.getMalls(dependencyId.mallIds).associateBy { it.mallId }
    57→                    }
    58→                }
    59→
    60→            Dependency(
    61→                categories = categoriesDeferred.await(),
    62→                brands = brandsDeferred.await(),
    63→                manufacturers = manufacturersDeferred.await(),
    64→                malls = mallsDeferred.await(),
    65→            )
    66→        }
    67→}
