     6→import org.springframework.stereotype.Component
     7→
     8→@Component
     9→class ManufacturerRepositoryImpl(
    10→    private val client: ProxyApiClient,
    11→) : ManufacturerRepository {
    12→    override fun findAllByIds(manufacturerIds: List<Long>): List<Manufacturer> {
    13→        val query =
    14→            """
    15→            query GetManufacturers(${'$'}ids: [Long!]) { # 스키마에 Long!으로 되어 있으니 타입을 맞춥니다.
    16→                manufacturers(input: { 
    17→                    byManufacturer: { 
    18→                        ids: ${'$'}ids 
    19→                    } 
    20→                }) {
    21→                    items {
    22→                        id
    23→                        name
    24→                    }
    25→                }
    26→            }
    27→            """.trimIndent()
    28→
    29→        return client.query(
    30→            query = query,
    31→            variables = mapOf("ids" to manufacturerIds),
    32→            retrievePath = "manufacturers.items",
    33→            Manufacturer::class.java,
    34→        )
    35→    }
    36→}
